import{_ as l,l as n,o as e,c as s,v as o,p as i,x as t,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"死锁四个条件","description":"","frontmatter":{"title":"死锁四个条件","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deadlock-coffman.md","filePath":"cs/deadlock-coffman.md","lastUpdated":1789023840000}'),p={name:"cs/deadlock-coffman.md"};function h(m,a,_,f,A,B){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="死锁四个条件" tabindex="-1">死锁四个条件 <a class="header-anchor" href="#死锁四个条件" aria-label="Permalink to &quot;死锁四个条件&quot;">​</a></h1><div class="epigraph"><p>死锁：一组进程中每一个都在等只能由该组内另一进程释放的资源。</p><footer>—— 据 Coffman, Elphick and Shoshani, System Deadlocks, Computing Surveys 1971 整理</footer></div><p><a href="/cs/lockfree-aba">上一课</a>让对象内部的等待变清楚。两个管程、两把锁、两个信号量仍可互相等。缺口不是再换一种原语，而是刻画<strong>何时等待集合永远走不出来</strong>。Coffman 四个必要条件把现象收成可检查的清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线程 A 持锁 \\(L_1\\) 等 \\(L_2\\)，线程 B 持 \\(L_2\\) 等 \\(L_1\\)。调度再公平也没用：没有人会 V 或 <code>signal</code> 到对方需要的那个。缺口是给出充要直觉：互斥、占有并等待、不可抢占、循环等待。四条同时成立才可能死锁；破坏任一条即可预防。</p><p>本课不引入银行家对「安全序列」的计算，那是下一课回避算法。这里只诊断条件。</p><p><span class="marginnote">资源分配图：进程指向它在等的资源，资源指向占有者。有向环（可重用资源、单实例）即循环等待的图说法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐条对照：互斥——资源一次一个（锁、内核缓冲槽）；占有并等待——已拿 \\(L_1\\) 再去拿 \\(L_2\\)；不可抢占——不能从持有者夺走锁；循环等待——等待图有环。预防：允许抢占（少见）、一次性申请全部、或对锁排序破坏环。检测：跑时找环；恢复：杀进程或抢资源。</p>',9)),(e(),i(c,null,{default:t(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%BA%92%E6%96%A5%22%5D%20--%3E%20D%5B%22%E5%9B%9B%E6%9D%A1%E5%90%8C%E6%97%B6%3A%20%E5%8F%AF%E8%83%BD%E6%AD%BB%E9%94%81%22%5D%0A%20%20H%5B%22%E5%8D%A0%E6%9C%89%E5%B9%B6%E7%AD%89%E5%BE%85%22%5D%20--%3E%20D%0A%20%20N%5B%22%E4%B8%8D%E5%8F%AF%E6%8A%A2%E5%8D%A0%22%5D%20--%3E%20D%0A%20%20C%5B%22%E5%BE%AA%E7%8E%AF%E7%AD%89%E5%BE%85%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20BANK%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%9B%9E%E9%81%BF%E4%B8%8E%E5%AE%89%E5%85%A8%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四个条件把「锁用得不对」从道德指责变成结构性质。管程内部互斥满足第一条；跨管程调用把后三条请进来。信号量没有持有者概念，循环等待仍可发生在 P 的集合上。实时课点过的优先级反转是活锁或延迟，不一定是死锁：低优先级最终可能跑完——死锁是<strong>永远</strong>等不到。</p><p>饥饿与死锁不同：饥饿是调度不公，图中未必有环。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理分布式死锁的探针算法，不把数据库锁表当 OS 课的同一套实现。可消耗资源（信号）的图判定与可重用资源不同，主干以可重用锁为准。也不把活锁（忙等协议永远错过）混进四个条件。</p><p>活锁是协议永远错过（忙等互相让路），图中无环也可发生；四个条件不刻画它。</p><p>后课默认：死锁可用四条件讨论，预防靠破其中一条。若允许动态申请但要求系统始终留在「存在安全序列」的状态，下一课银行家算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>死锁：组内循环互等；Coffman 四条件同时成立。</li><li>破任一条件即预防；找环是检测。</li><li>安全序列与回避是银行家的缺口。</li><li>出处：Coffman, Elphick and Shoshani, <em>Computing Surveys</em>, 1971；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const k=l(p,[["render",h]]);export{D as __pageData,k as default};
